import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns

from sklearn.cluster import DBSCAN
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import mean_squared_error, mean_absolute_error, r2_score
from sklearn.linear_model import Ridge, Lasso
from sklearn.ensemble import RandomForestRegressor
from sklearn.svm import SVR

# 1. Load the clean dataset generated by 1_extract_and_filter.py
df = pd.read_csv("punjab_haryana_stubble_2020_2025.csv")
df['acq_date'] = pd.to_datetime(df['acq_date'])

# 2. Spatial Clustering (DBSCAN to identify fire hotspots)
coords = df[['latitude', 'longitude']].values
dbscan = DBSCAN(eps=0.1, min_samples=15)
df['cluster_id'] = dbscan.fit_predict(coords)

num_clusters = len(set(df['cluster_id'])) - (1 if -1 in df['cluster_id'] else 0)
print(f"DBSCAN identified {num_clusters} spatial hotspot clusters across Punjab & Haryana.")

# 3. Daily Aggregation & Feature Engineering
daily_df = df.groupby('acq_date').agg(
    fire_count_t=('frp', 'count'),
    total_frp_t=('frp', 'sum')
).reset_index().sort_values('acq_date').reset_index(drop=True)

# Build Lag Features (Past Days)
daily_df['fire_count_lag1'] = daily_df['fire_count_t'].shift(1)
daily_df['fire_count_lag2'] = daily_df['fire_count_t'].shift(2)
daily_df['frp_lag1'] = daily_df['total_frp_t'].shift(1)
daily_df['rolling_3d_mean'] = daily_df['fire_count_t'].rolling(3).mean()

# Seasonal Cyclical Encoding (Day of Year)
doy = daily_df['acq_date'].dt.dayofyear
daily_df['doy_sin'] = np.sin(2 * np.pi * doy / 365.0)
daily_df['doy_cos'] = np.cos(2 * np.pi * doy / 365.0)

# Target Variable: Next-Day Fire Count (t+1)
daily_df['target_fire_count_t1'] = daily_df['fire_count_t'].shift(-1)
daily_df = daily_df.dropna().reset_index(drop=True)

# 4. Chronological Train / Test Split (Train: <=2023 | Test: >=2024)
features = ['fire_count_t', 'fire_count_lag1', 'fire_count_lag2', 'frp_lag1', 'rolling_3d_mean', 'doy_sin', 'doy_cos']

train_mask = daily_df['acq_date'].dt.year <= 2023
test_mask = daily_df['acq_date'].dt.year >= 2024

X_train, y_train = daily_df.loc[train_mask, features], daily_df.loc[train_mask, 'target_fire_count_t1']
X_test, y_test = daily_df.loc[test_mask, features], daily_df.loc[test_mask, 'target_fire_count_t1']

scaler = StandardScaler()
X_train_scaled = scaler.fit_transform(X_train)
X_test_scaled = scaler.transform(X_test)

# 5. Evaluate Regressors vs. Persistence Baseline
y_pred_baseline = X_test['fire_count_t']

models = {
    'Persistence Baseline': None,
    'Ridge Regression': Ridge(alpha=10.0),
    'Lasso Regression': Lasso(alpha=1.0),
    'Support Vector Regressor': SVR(kernel='rbf', C=10.0, epsilon=1.0),
    'Random Forest Regressor': RandomForestRegressor(n_estimators=100, max_depth=6, random_state=42)
}

results = []
for name, model in models.items():
    if name == 'Persistence Baseline':
        y_pred = y_pred_baseline
    else:
        model.fit(X_train_scaled, y_train)
        y_pred = model.predict(X_test_scaled)
    
    results.append({
        'Model': name,
        'MAE': round(mean_absolute_error(y_test, y_pred), 2),
        'RMSE': round(np.sqrt(mean_squared_error(y_test, y_pred)), 2),
        'R2 Score': round(r2_score(y_test, y_pred), 4)
    })

print("\n" + "="*55)
print("     SUMMARY TABLE: NEXT-DAY FIRE FORECASTING")
print("="*55)
print(pd.DataFrame(results).to_string(index=False))

# 6. Plot Hotspot Map and Predictions
fig, axes = plt.subplots(1, 2, figsize=(14, 5))

# Plot 1: DBSCAN Spatial Hotspots
sns.scatterplot(
    ax=axes[0], data=df, 
    x='longitude', y='latitude', hue='cluster_id', 
    palette='tab10', s=15, alpha=0.8
)
axes[0].set_title('DBSCAN Spatial Hotspot Clusters (Punjab & Haryana)')
axes[0].set_xlabel('Longitude')
axes[0].set_ylabel('Latitude')

# Plot 2: Forecast comparison
rf = RandomForestRegressor(n_estimators=100, max_depth=6, random_state=42)
rf.fit(X_train_scaled, y_train)
rf_preds = rf.predict(X_test_scaled)

axes[1].plot(y_test.values, label='Observed Actual Fires ($N_{t+1}$)', color='black', linewidth=1.5)
axes[1].plot(rf_preds, label='Predicted (Random Forest)', color='firebrick', linestyle='--')
axes[1].set_title('Next-Day Fire Count Forecasting ($t+1$)')
axes[1].set_xlabel('Test Window (Days)')
axes[1].set_ylabel('Active Fire Count')
axes[1].legend()

plt.tight_layout()
plt.show()